export function detectOS(ua='',platform='',touch=0){if(/android/i.test(ua))return 'android';if(/iphone|ipad|ipod/i.test(ua)||(/Mac/i.test(platform)&&touch>1))return 'ios';if(/windows/i.test(ua))return 'windows';if(/macintosh|mac os/i.test(ua))return 'macos';if(/linux/i.test(ua))return 'linux';return '';}
export function matches(filename,os,arch){const n=filename.toLowerCase();if(/checksum|sha256|dsym|evidence|\.sig$|\.asc$|\.sha/.test(n))return false;if(os==='ios')return false;if(os==='android')return n.endsWith('.apk')&&(arch==='unknown'?/universal/.test(n):/universal/.test(n)|| (arch==='arm64'?/arm64|aarch64|arm64-v8a/.test(n):arch==='amd64'?/amd64|x86_64|x64/.test(n):/armv7|armeabi-v7a/.test(n)));if(arch==='unknown')return false;const architecture=arch==='arm64'?/arm64|aarch64/:arch==='amd64'?/amd64|x86_64|x64/:/armv7/;if(!architecture.test(n))return false;if(os==='windows')return (/windows|win32|win64/.test(n)||/\.(exe|msi)$/.test(n))&&/\.(exe|msi|zip)$/.test(n);if(os==='macos')return (/darwin|macos|apple/.test(n)||/\.(dmg|pkg)$/.test(n))&&/\.(dmg|pkg|zip|tar\.gz|tgz|bin)$/.test(n);if(os==='linux')return (/linux/.test(n)||/\.(deb|rpm|appimage)$/.test(n))&&/\.(deb|rpm|appimage|tar\.gz|tar\.xz|tgz|zip|sh|bin)$/.test(n);return false;}

export function isPrimaryAsset(repo,name){if(repo==='openai/codex')return /^codex-(aarch64|x86_64|x64|arm64)[-.]/i.test(name)&&!name.includes('bazel');return !/dsym|evidence|checksum|sigstore|debug|noembedded|^bwrap-|^argument-comment-lint-/i.test(name);}
